function assertValidNucleiTemplatePath(filePath) {
  if (filePath.includes("\0")) {
    throw new Error("Invalid template file path.");
  }
  if (!/\.ya?ml$/i.test(filePath)) {
    throw new Error("Nuclei template file must be a .yaml or .yml file.");
  }
}

