// src/utils/semaphore.ts
var Semaphore = class {
  available;
  waiters = [];
  constructor(max) {
    this.available = max;
  }
  async run(task) {
    if (this.available > 0) {
      this.available--;
    } else {
      await new Promise((resolve2) => this.waiters.push(resolve2));
    }
    try {
      return await task();
    } finally {
      const next = this.waiters.shift();
      if (next) {
        next();
      } else {
        this.available++;
      }
    }
  }
};

// src/utils/output-naming.ts
function languageOutputPath(outputFile, lang) {
  const ext = outputFile.match(/\.(json|yaml|yml)$/)?.[0] ?? "";
  return `${outputFile.replace(/\.(json|yaml|yml)$/, "")}_${lang}${ext}`;
}

// src/utils/discover-output-path.ts
function resolveActualOutputFile(requestedPath, exists) {
  if (exists(requestedPath)) {
    return requestedPath;
  }
  const base = requestedPath.replace(/\.(json|yaml|yml)$/, "");
  for (const candidate of [`${base}.yml`, `${base}.yaml`]) {
    if (candidate !== requestedPath && exists(candidate)) {
      return candidate;
    }
  }
  return null;
}

