// src/config/token.ts
import * as fs from "fs";
import * as path from "path";
import * as os from "os";
var CONFIG_DIR = path.join(os.homedir(), ".nightvision");
var TOKEN_FILE = path.join(CONFIG_DIR, "token");
function loadToken() {
  try {
    if (fs.existsSync(TOKEN_FILE)) {
      return fs.readFileSync(TOKEN_FILE, "utf8").trim();
    }
  } catch (error51) {
    console.error(`Failed to load token: ${error51}`);
  }
  return null;
}
function saveToken(token) {
  try {
    if (!fs.existsSync(CONFIG_DIR)) {
      fs.mkdirSync(CONFIG_DIR, { recursive: true, mode: 448 });
    }
    fs.writeFileSync(TOKEN_FILE, token, { mode: 384 });
    fs.chmodSync(TOKEN_FILE, 384);
  } catch (error51) {
    console.error(`Failed to save token: ${error51}`);
  }
}
function clearToken() {
  try {
    if (fs.existsSync(TOKEN_FILE)) {
      fs.unlinkSync(TOKEN_FILE);
    }
  } catch (error51) {
    console.error(`Failed to clear token: ${error51}`);
  }
}

