// src/utils/check-catalog.ts
function getAllAlertIds(checks) {
  const standard = checks.zap.standard?.map((a) => a.Id) || [];
  const web = checks.zap.web?.map((a) => a.Id) || [];
  return [...standard, ...web];
}
function getExclusionIds(checks, includeNames) {
  const lowerNames = includeNames.map((n) => n.toLowerCase());
  const allAlerts = [
    ...checks.zap.standard || [],
    ...checks.zap.web || []
  ];
  const matched = [];
  for (const alert of allAlerts) {
    const alertLower = alert.Alert.toLowerCase();
    if (lowerNames.some((n) => alertLower.includes(n) || n.includes(alertLower))) {
      matched.push(alert);
    }
  }
  const includeIds = new Set(matched.map((a) => a.Id));
  const allIds = getAllAlertIds(checks);
  const excludeIds = allIds.filter((id) => !includeIds.has(id));
  return {
    excludeIds,
    matchedAlerts: matched.map((a) => `${a.Alert} [${a.Id}]`)
  };
}
function getNucleiExclusionFolders(checks, includeNames) {
  const lowerNames = includeNames.map((n) => n.toLowerCase());
  const allFolders = checks.nuclei || [];
  const matched = allFolders.filter((folder) => {
    const folderLower = folder.toLowerCase();
    return lowerNames.some((n) => folderLower.includes(n) || n.includes(folderLower));
  });
  const includeSet = new Set(matched);
  const excludeFolders = allFolders.filter((f) => !includeSet.has(f));
  return { excludeFolders, matchedFolders: matched };
}
function formatCheckList(checks) {
  const lines = [];
  if (checks.zap.standard?.length) {
    lines.push("Standard ZAP Checks:");
    for (const a of checks.zap.standard) {
      lines.push(`  - ${a.Alert} [${a.Id}] (${a.Risk})`);
    }
  }
  if (checks.zap.web?.length) {
    lines.push("\nWeb-Only ZAP Checks:");
    for (const a of checks.zap.web) {
      lines.push(`  - ${a.Alert} [${a.Id}] (${a.Risk})`);
    }
  }
  if (checks.nuclei?.length) {
    lines.push("\nNuclei Folders:");
    for (const folder of checks.nuclei) {
      lines.push(`  - ${folder}`);
    }
  }
  return lines.join("\n");
}

// src/utils/scan-findings-summary.ts
var SEVERITY_RANK = {
  critical: 0,
  high: 1,
  medium: 2,
  low: 3,
  info: 4,
  informational: 4,
  unknown: 5,
  unspecified: 6
};
function severityKey(value) {
  return String(value || "unknown").trim().toLowerCase();
}
function title2(check2) {
  return check2.name || check2.kind || null;
}
function firstString(...values) {
  for (const value of values) {
    if (typeof value === "string" && value.trim()) {
      return value;
    }
  }
  return null;
}
function endpoint(check2) {
  const method = firstString(check2.method, check2.http_method, check2.request_method);
  const path12 = firstString(check2.path, check2.route, check2.endpoint_path);
  const url3 = firstString(check2.url, check2.uri, check2.location);
  if (!method && !path12 && !url3) {
    return null;
  }
  return { method, path: path12, url: url3 };
}
function summarizeScanChecks(response, limit = 20) {
  const results = Array.isArray(response?.results) ? response.results : [];
  const sorted = [...results].sort((a, b) => {
    const aRank = SEVERITY_RANK[severityKey(a.severity)] ?? 99;
    const bRank = SEVERITY_RANK[severityKey(b.severity)] ?? 99;
    return aRank - bRank;
  });
  const page_severity_counts = {};
  for (const check2 of results) {
    const key = severityKey(check2.severity);
    page_severity_counts[key] = (page_severity_counts[key] || 0) + 1;
  }
  const findings = sorted.slice(0, Math.max(0, limit)).map((check2) => ({
    id: check2.id || null,
    title: title2(check2),
    kind: check2.kind || null,
    severity: check2.severity || null,
    status: check2.status ?? null,
    endpoint: endpoint(check2),
    parameter: firstString(check2.parameter, check2.param, check2.attack_parameter),
    evidence: firstString(check2.evidence, check2.proof, check2.response_evidence),
    ai_explanation: firstString(check2.ai_explanation, check2.explanation)
  }));
  const total_count = response?.count ?? results.length;
  return {
    total_count,
    returned_count: results.length,
    summarized_count: findings.length,
    page_severity_counts,
    findings,
    // truncated reflects the SERVER total, not just this page: it is true when
    // the summary omits any finding, whether dropped by the display limit or by
    // server-side pagination (results is one page; total_count is the API total).
    truncated: findings.length < total_count
  };
}

