function registerTrafficTools(server) {
  registerNightVisionTool(
    server,
    "record-traffic",
    RecordTrafficParamsSchema,
    async (args, _extra) => {
      try {
        const {
          name,
          url: url3,
          target,
          project,
          format = "text"
        } = args;
        const authGuard = await requireAuthenticatedUser();
        if (!authGuard.ok) return authGuard.response;
        const projectAccess = await requireProjectAccess({
          project,
          action: "recording traffic"
        });
        if (!projectAccess.ok) return projectAccess.response;
        try {
          const browserInfo = `
This tool will open a browser window for you to interact with the target application.
1. The browser will open automatically at ${url3}
2. Navigate through the application to generate traffic
3. When finished, close the browser window
4. The traffic will be automatically recorded as a HAR file and uploaded to NightVision
`;
          const result = await nightvision_default.recordTraffic(
            name,
            url3,
            target,
            project,
            format
          );
          return {
            content: [{
              type: "text",
              text: `${browserInfo}
Traffic recording completed:

${result}`
            }]
          };
        } catch (error51) {
          console.error(`Error recording traffic: ${error51.message}`);
          return {
            content: [{
              type: "text",
              text: `Failed to record traffic: ${error51.message}`
            }],
            isError: true
          };
        }
      } catch (error51) {
        return {
          content: [{
            type: "text",
            text: `Failed to record traffic: ${error51.message}`
          }],
          isError: true
        };
      }
    }
  );
  registerNightVisionTool(
    server,
    "list-traffic",
    ListTrafficParamsSchema,
    async (args, _extra) => {
      try {
        const {
          target,
          project,
          format = "json"
        } = args;
        const authGuard = await requireAuthenticatedUser();
        if (!authGuard.ok) return authGuard.response;
        const projectAccess = await requireProjectAccess({
          project,
          action: "listing traffic"
        });
        if (!projectAccess.ok) return projectAccess.response;
        try {
          const result = await nightvision_default.listTraffic(
            target,
            project,
            format
          );
          return {
            content: [{
              type: "text",
              text: `Traffic files for target ${target} in project ${project}:

${result}`
            }]
          };
        } catch (error51) {
          console.error(`Error listing traffic files: ${error51.message}`);
          return {
            content: [{
              type: "text",
              text: `Failed to list traffic files: ${error51.message}`
            }],
            isError: true
          };
        }
      } catch (error51) {
        return {
          content: [{
            type: "text",
            text: `Failed to list traffic files: ${error51.message}`
          }],
          isError: true
        };
      }
    }
  );
  registerNightVisionTool(
    server,
    "download-traffic",
    DownloadTrafficParamsSchema,
    async (args, _extra) => {
      try {
        const {
          name,
          target,
          project,
          output_file,
          downloadPath: initialDownloadPath,
          format = "text"
        } = args;
        const authGuard = await requireAuthenticatedUser();
        if (!authGuard.ok) return authGuard.response;
        const projectAccess = await requireProjectAccess({
          project,
          action: "downloading traffic"
        });
        if (!projectAccess.ok) return projectAccess.response;
        const path12 = await import("path");
        const fs3 = await import("fs");
        const os4 = await import("os");
        const isWritable = (dir) => {
          try {
            fs3.accessSync(dir, fs3.constants.W_OK);
            return true;
          } catch {
            return false;
          }
        };
        const downloadPath = resolveDownloadDir(initialDownloadPath, os4.homedir(), os4.tmpdir(), isWritable);
        console.error(`Resolved download directory: ${downloadPath}`);
        const finalOutputPath = output_file ? path12.isAbsolute(output_file) ? output_file : path12.join(downloadPath, output_file) : path12.join(downloadPath, `${name}.har`);
        const result = await nightvision_default.downloadTraffic(
          name,
          target,
          project,
          finalOutputPath,
          downloadPath,
          format
        );
        const downloadMessage = `The traffic file "${name}" has been downloaded for target "${target}" in project "${project}".

The HAR file is saved at the absolute path: ${finalOutputPath}

Download directory used: ${downloadPath}`;
        return {
          content: [{
            type: "text",
            text: `${downloadMessage}

${result}`
          }]
        };
      } catch (error51) {
        return {
          content: [{
            type: "text",
            text: `Failed to download traffic file: ${error51.message}`
          }],
          isError: true
        };
      }
    }
  );
}

